using namespace std;

class Solution {
public:
    string generateString(string str1, string str2) {
        int n = str1.size(), m = str2.size();
        int sz = n + m - 1;
        string ans(sz, '\0');
        vector<bool> fixed(sz, false);

        for (int i = 0; i < n; i++) {
            if (str1[i] == 'T') {
                for (int j = 0; j < m; j++) {
                    int pos = i + j;
                    if (ans[pos] != '\0' && ans[pos] != str2[j]) return "";
                    ans[pos] = str2[j];
                    fixed[pos] = true;
                }
            }
        }

        for (int i = 0; i < sz; i++) {
            if (ans[i] == '\0') ans[i] = 'a';
        }

        for (int i = 0; i < n; i++) {
            if (str1[i] == 'F') {
                bool match = true;
                for (int j = 0; j < m; j++) {
                    if (ans[i + j] != str2[j]) {
                        match = false;
                        break;
                    }
                }
                if (match) {
                    int modifiable = -1;
                    for (int j = m - 1; j >= 0; j--) {
                        int pos = i + j;
                        if (!fixed[pos]) {
                            modifiable = pos;
                            break;
                        }
                    }
                    if (modifiable == -1) return "";
                    ans[modifiable] = 'b';
                    fixed[modifiable] = true;
                }
            }
        }

        for (int i = 0; i < n; i++) {
            bool match = true;
            for (int j = 0; j < m; j++) {
                if (ans[i + j] != str2[j]) {
                    match = false;
                    break;
                }
            }
            if (str1[i] == 'T' && !match) return "";
            if (str1[i] == 'F' && match) return "";
        }

        return ans;
    }
};

