    const n = str1.length, m = str2.length;
    const sz = n + m - 1;
    const ans = new Array(sz).fill(null);
    const fixed = new Array(sz).fill(false);

    for (let i = 0; i < n; i++) {
        if (str1[i] === 'T') {
            for (let j = 0; j < m; j++) {
                const pos = i + j;
                if (ans[pos] !== null && ans[pos] !== str2[j]) return "";
                ans[pos] = str2[j];
                fixed[pos] = true;
            }
        }
    }

