                        break;
                    }
                }
                if (modifiable === -1) return "";
                ans[modifiable] = 'b';
                fixed[modifiable] = true;
            }
        }
    }

    for (let i = 0; i < n; i++) {
        let match = true;
        for (let j = 0; j < m; j++) {
            if (ans[i + j] !== str2[j]) {
                match = false;
                break;
            }
